    coalesce((coalesce((role <> 'owner'), false)
    AND (coalesce("members"."user_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."chat__manage" v WHERE v.id = "members"."chat_id"))), false),
    coalesce((SELECT authz_int.scope_cmd('ms.members', 'delete')), false),
    coalesce(true, false),
    coalesce((coalesce("members"."user_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."chat__manage" v WHERE v.id = "members"."chat_id")), false),
    coalesce(coalesce("members"."user_id" = (SELECT authz.uid()), false), false),
    coalesce(EXISTS (SELECT 1 FROM authz_int."chat__manage" v WHERE v.id = "members"."chat_id"), false),
    coalesce(coalesce((role <> 'owner'), false), false)]
    ELSE pg_catalog.array_fill(false, ARRAY[7]) END
  FROM pg_catalog.unnest(ARRAY[p_row]) AS "members";
END;

CREATE OR REPLACE FUNCTION authz_gen."ms.members:delete:why"(p_row "ms"."members") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."ms.members:delete:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'delete : (person or chat.manage) and {role <> ''owner''}  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule ms.members delete'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow delete on ms.members'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || '(person or chat.manage)';
  IF NOT v[4] THEN
    RETURN NEXT CASE WHEN v[5] THEN '    yes  ' ELSE '    no   ' END || 'person';
    RETURN NEXT CASE WHEN v[6] THEN '    yes  ' ELSE '    no   ' END || 'chat.manage';
  IF NOT v[6] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ("members"."chat_id")::text AS id FROM (SELECT (p_row).*) AS "members") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '      ' || l FROM authz.explain('chat', v_t.id, 'manage') l LIMIT 20;
    END LOOP;
  END IF;
  END IF;
  RETURN NEXT CASE WHEN v[7] THEN '  yes  ' ELSE '  no   ' END || '{role <> ''owner''}';
END $f$;

-- ms.members delete (line 98): (person or chat.manage) and {role <> 'owner'}
CREATE POLICY "authz_delete" ON "ms"."members" FOR DELETE TO "ms_app"
  USING (((SELECT authz_int.scope_cmd('ms.members', 'delete')) AND (coalesce((role <> 'owner'), false)
    AND (coalesce("members"."user_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."chat__manage" v WHERE v.id = "members"."chat_id")))));
COMMENT ON POLICY "authz_delete" ON "ms"."members" IS 'rowstile';

CREATE FUNCTION authz_gen."ms.messages:column edited_at:items"(p_row "ms"."messages") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT CASE WHEN authz_int."ms.messages:seen"(ROW("messages"."chat_id"::bigint, "messages"."seq"::bigint)::text) THEN ARRAY[
    coalesce((coalesce("messages"."sender_id" = (SELECT authz.uid()), false)
    AND coalesce((not deleted and created_at > now() - interval '15 minutes'), false)), false),
    coalesce((SELECT authz_int.scope_cmd('ms.messages', 'update')), false),
    coalesce(true, false),
    coalesce((coalesce("messages"."sender_id" = (SELECT authz.uid()), false)
    AND coalesce((not deleted and created_at > now() - interval '15 minutes'), false)), false)]
    ELSE pg_catalog.array_fill(false, ARRAY[4]) END
  FROM pg_catalog.unnest(ARRAY[p_row]) AS "messages";
END;

CREATE FUNCTION authz_gen."ms.messages:column edited_at:why"(p_row "ms"."messages") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."ms.messages:column edited_at:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'update edited_at : edit  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule ms.messages update edited_at'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow update on ms.messages'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'edit';
  IF NOT v[4] THEN
    RETURN QUERY SELECT '    ' || l FROM authz.explain('message', (ROW((p_row)."chat_id"::bigint, (p_row)."seq"::bigint)::text), 'edit') l LIMIT 20;
  END IF;
END $f$;

-- ms.messages update edited_at (line 110): edit
-- Whether the rule holds for a row: called by the trigger's WHEN, which is kept parsed, as a policy is, so the app
-- role uses it without naming it (authz_int)
CREATE FUNCTION authz_int."ms.messages:column edited_at:holds"(p_row "ms"."messages") RETURNS boolean
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT coalesce((coalesce("messages"."sender_id" = (SELECT authz.uid()), false)
    AND coalesce((not deleted and created_at > now() - interval '15 minutes'), false)), false) FROM pg_catalog.unnest(ARRAY[p_row]) AS "messages";
END;

-- refused: says why. The rule is checked in the trigger's WHEN below
CREATE FUNCTION authz_int."ms.messages:column edited_at"() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $f$
DECLARE v_lines text; v_row "ms"."messages";
BEGIN
  -- the row as the table's own: a partition's columns may be in another order, a table that inherits may have more
  IF TG_RELID = '"ms"."messages"'::pg_catalog.regclass THEN v_row := OLD;
  ELSE v_row := pg_catalog.jsonb_populate_record(NULL::"ms"."messages", pg_catalog.to_jsonb(OLD)); END IF;
  BEGIN
    v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."ms.messages:column edited_at:why"(v_row) l);
  EXCEPTION WHEN OTHERS THEN
    v_lines := 'no explanation: ' || SQLERRM;
  END;
  RAISE EXCEPTION 'changing edited_at of ms.messages % needs: edit', ROW(OLD."chat_id"::bigint, OLD."seq"::bigint)::text USING ERRCODE = 'insufficient_privilege', DETAIL = v_lines,
    SCHEMA = 'ms', TABLE = 'messages', CONSTRAINT = 'authz_update', HINT = 'rowstile help AZ709';
END $f$;

-- checked on the row before the change, for roles that row-level security applies to on the
-- table (not on TG_RELID: on a partition made since the policy was applied, where it is not on yet, this runs too),
-- the row as the table's own
CREATE TRIGGER "authz_update edited_at" BEFORE UPDATE ON "ms"."messages" FOR EACH ROW
  WHEN ((OLD."edited_at" IS DISTINCT FROM NEW."edited_at")
    AND pg_catalog.row_security_active('"ms"."messages"'::pg_catalog.regclass)
    AND NOT authz_int."ms.messages:column edited_at:holds"(pg_catalog.jsonb_populate_record(NULL::"ms"."messages", pg_catalog.to_jsonb(OLD))))
  EXECUTE FUNCTION authz_int."ms.messages:column edited_at"();

